#include <list>
#include <vector>

struct NonDefault {
    int val;
    NonDefault(int v) : val(v) {} // Custom constructor
    // NonDefault() = delete; // If deleted, list(n) fails
};

int main() {
    // 1. Range initialization (safe, copies elements)
    std::vector<int> source = {1, 2, 3};
    std::list<int> l1(source.begin(), source.end());

    // 2. Fill (N copies)
    std::list<NonDefault> l2(5, NonDefault(10)); // Requires CopyConstructible

    // 3. Fill (N default elements) - Requires DefaultConstructible
    std::list<int> l3(10); 

    // std::list<NonDefault> l4(10); // Fails if NonDefault() is deleted
}
